/* @lc app=leetcode id=3212 lang=kotlin */ class Solution { fun pre(g: Array<CharArray>, ch: Char): Array<IntArray> = Array(g.size) { IntArray(g[0].size) }.also { p -> g.indices.forEach { i -> g[0].indices.forEach { j -> p[i][j] = (if (g[i][j] == ch) 1 else 0) + (if (i > 0) p[i - 1][j] else 0) + (if (j > 0) p[i][j - 1] else 0) - (if (i > 0 && j > 0) p[i - 1][j - 1] else 0) } } } fun numberOfSubmatrices(grid: Array<CharArray>): Int = pre(grid, 'X').let { px -> pre(grid, 'Y').let { py -> (0 until grid.size * grid[0].size).count { px[it / grid[0].size][it % grid[0].size] > 0 && px[it / grid[0].size][it % grid[0].size] == py[it / grid[0].size][it % grid[0].size] } } } }